def compute(vars):
    value = vars["v1"] - vars["v2"]
    return {
        "value": value,
        "trace": {
            "trading_assets_excluding_derivatives": vars["v1"],
            "trading_liabilities_excluding_derivatives": vars["v2"],
            "net_trading_assets": value,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
